function navigate(route){
  document.querySelectorAll(".page").forEach(p=>p.classList.remove("active"));
  const isClub=route.startsWith("club/");
  const target=isClub?"club":(["inicio","equipos","apertura","clausura","liga-general","copa-apertura","copa-clausura","ranking-rf","normativa","faq","sorteos"].includes(route)&&!(route==="sorteos"&&!data.draw.enabled)?route:"inicio");
  document.getElementById(target).classList.add("active");
  document.querySelectorAll(".nav a").forEach(a=>a.classList.toggle("active",a.dataset.route===target));
  if(isClub){
    const index=Number(route.split("/")[1]);const club=data.clubs[index];
    if(club){currentClubIndex=index;
      document.getElementById("clubName").textContent=club.name;
      document.getElementById("clubManager").textContent=club.manager;
      document.getElementById("clubMotto").textContent=club.motto||"La historia está a punto de escribirse.";
      const kitImage=document.getElementById("clubKitImage"),crestImage=document.getElementById("clubDisplayCrest");kitImage.src=club.kit||"";kitImage.hidden=!club.kit;kitImage.nextElementSibling.hidden=Boolean(club.kit);crestImage.src=club.crest||"";crestImage.hidden=!club.crest;crestImage.nextElementSibling.hidden=Boolean(club.crest);
      renderMatchdays(club);
      const activeBadges=club.badges.filter(b=>b.name||b.image);document.getElementById("clubBadges").innerHTML=`<div class="official-title-badges">${COMPETITION_NAMES.map((name,t)=>titleBadgeMarkup(name,club.titleWins[t],t)).join("")}</div>${activeBadges.map(b=>`<div class="club-badge">${b.image?`<img src="${esc(b.image)}" alt="${esc(b.name||'Insignia')}">`:`<span class="badge-placeholder">★</span>`}<strong>${esc(b.name||"Insignia")}</strong></div>`).join("")}`;
      const crest=document.getElementById("clubCrest");crest.textContent=club.crest?"":initials(club.name,index);crest.classList.toggle("has-image",Boolean(club.crest));crest.style.backgroundImage=club.crest?`url("${club.crest}")`:"";crest.style.backgroundSize="contain";crest.style.backgroundPosition="center";crest.style.backgroundRepeat="no-repeat";
    }
  }
  document.getElementById("mainNav").classList.remove("open");window.scrollTo(0,0);
}
